{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "oneOf": [
    {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "description": "Frontmatter of a file under teams/<team>/adr/ or cross-cutting/adr/.",
      "properties": {
        "applies_to": {
          "description": "Paths this decision governs.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            }
          ]
        },
        "date": {
          "format": "date",
          "type": "string"
        },
        "deciders": {
          "description": "Who made the decision.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            }
          ]
        },
        "id": {
          "pattern": "^ADR-\\d{4}$",
          "type": "string"
        },
        "schema_version": {
          "const": 1,
          "type": "integer"
        },
        "status": {
          "enum": [
            "Proposed",
            "Accepted",
            "Rejected",
            "Deprecated",
            "Superseded"
          ],
          "type": "string"
        },
        "superseded_by": {
          "description": "Required when status is Superseded.",
          "items": {
            "pattern": "^([a-z0-9][a-z0-9-]*/)?ADR-\\d{4}$",
            "type": "string"
          },
          "type": "array"
        },
        "supersedes": {
          "description": "The reverse pointer, written by jerry supersede.",
          "items": {
            "pattern": "^([a-z0-9][a-z0-9-]*/)?ADR-\\d{4}$",
            "type": "string"
          },
          "type": "array"
        },
        "team": {
          "description": "Must match the folder under teams/.",
          "type": "string"
        },
        "teams": {
          "description": "Cross-cutting ADRs use this instead of team.",
          "items": {
            "type": "string"
          },
          "minItems": 2,
          "type": "array"
        },
        "title": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "id",
        "title",
        "status",
        "date",
        "deciders"
      ],
      "title": "Architecture Decision Record frontmatter",
      "type": "object"
    },
    {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "description": "Frontmatter of a file under teams/<team>/solution-designs/.",
      "properties": {
        "applies_to": {
          "description": "Paths this design covers.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            }
          ]
        },
        "authors": {
          "description": "Who wrote the design.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            }
          ]
        },
        "date": {
          "format": "date",
          "type": "string"
        },
        "related_adrs": {
          "description": "ADRs this design produced or depends on.",
          "items": {
            "pattern": "^([a-z0-9][a-z0-9-]*/)?ADR-\\d{4}$",
            "type": "string"
          },
          "type": "array"
        },
        "schema_version": {
          "const": 1,
          "type": "integer"
        },
        "status": {
          "enum": [
            "Draft",
            "In Review",
            "Approved",
            "Implemented",
            "Superseded",
            "Archived"
          ],
          "type": "string"
        },
        "team": {
          "type": "string"
        },
        "title": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "title",
        "status",
        "date",
        "authors"
      ],
      "title": "Solution Design frontmatter",
      "type": "object"
    }
  ],
  "title": "jerry documents"
}
